custom_css:
/* 玻璃标本室 · 自适应长文。正文不设固定高度，不建立内部滚动区。 */
:root { --glass-ink:#354b53; --glass-line:#c4d7da; --glass-avatar:104px; }
#bg1 { background-image:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/glass-specimen-room/background.webp')!important; background-size:cover!important; background-position:center!important; }
#sheld { background:transparent!important; }
#chat { background:rgba(239,248,250,.28)!important; padding:45px 18px 24px!important; }
#chat .mes { position:relative; isolation:isolate; box-sizing:border-box; width:calc(100% - 12px); margin:42px auto 38px!important; padding:20px 26px 42px!important; border:1px solid rgba(255,255,255,.98)!important; border-radius:22px!important; background:rgba(248,253,254,.94)!important; box-shadow:0 6px 20px rgba(61,91,101,.10),inset 0 0 0 1px rgba(193,215,220,.6)!important; height:auto!important; max-height:none!important; overflow:visible!important; color:var(--glass-ink); backdrop-filter:none!important; }
#chat .mes::before { content:''; position:absolute; right:0; bottom:0; width:155px; height:220px; background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/glass-specimen-room/etching.webp') right bottom/contain no-repeat; opacity:.22; pointer-events:none; z-index:-1; }
#chat .mes > .mesAvatarWrapper { display:contents!important; }
#chat .mes .mesAvatarWrapper > .avatar { position:absolute!important; top:-30px; left:24px; width:var(--glass-avatar)!important; height:128px!important; padding:6px!important; box-sizing:border-box; border:1px solid #fff; border-radius:17px!important; background:rgba(228,242,245,.95); box-shadow:0 3px 10px #47606c26; flex:none!important; }
#chat .mes .mesAvatarWrapper > .avatar img { width:100%!important; height:100%!important; max-height:none!important; object-fit:cover; border-radius:12px!important; }
#chat .mes .mesAvatarWrapper > :is(.mesIDDisplay,.mes_timer,.tokenCounterDisplay) { position:absolute; bottom:12px; margin:0!important; font-size:11px!important; line-height:18px; color:#728b93; }
#chat .mes .mesIDDisplay { left:26px; }
#chat .mes .mes_timer { left:86px; }
#chat .mes .tokenCounterDisplay { left:165px; }
#chat .mes > .mes_block { display:block!important; position:relative; min-width:0; width:100%!important; margin:0!important; padding:0!important; height:auto!important; max-height:none!important; overflow:visible!important; }
#chat .mes .ch_name { margin:0 0 15px calc(var(--glass-avatar) + 12px)!important; min-height:84px; height:auto!important; display:flex; flex-wrap:wrap; align-content:flex-start; align-items:center; gap:7px; padding:4px 0 12px; border-bottom:1px solid var(--glass-line); color:#45606a; }
#chat .mes .name_text { font-size:1.12em; letter-spacing:.05em; }
#chat .mes :is(.mes_buttons,.extraMesButtons) { flex-wrap:wrap; max-width:100%; color:#7d969e; }
#chat .mes .mes_text { width:100%!important; min-width:0; padding:0!important; margin:0!important; height:auto!important; max-height:none!important; overflow:visible!important; overflow-wrap:anywhere; line-height:1.85; font-size:1em; color:var(--glass-ink); }
#chat .mes .mes_text p { margin:.75em 0; }
#chat .mes .mes_text :is(pre,table) { max-width:100%; overflow-x:auto; }
#chat .mes .mes_text pre { white-space:pre; }
#chat .mes .mes_text img { max-width:100%; height:auto; }
#chat .mes .mes_text blockquote { border-left:2px solid #a8c4cb; margin:1em 0; padding:.25em 1em; background:#e9f3f580; color:#64818a; }
#chat .mes[is_user="true"] { width:88%; margin-left:auto!important; margin-right:0!important; background:rgba(241,249,247,.96)!important; }
#chat .mes[is_user="true"] .mesAvatarWrapper > .avatar { left:auto; right:24px; width:80px!important; height:94px!important; }
#chat .mes[is_user="true"] .ch_name { margin-left:0!important; margin-right:88px!important; min-height:58px; }
#chat .mes[is_system="true"] { margin-top:14px!important; }
#chat .mes[is_system="true"] .ch_name { min-height:0; }
#chat .mes .mes_reasoning_details { border:1px solid #cbdde1; border-radius:10px; background:#edf6f8; padding:8px 12px; margin:12px 0; }
#top-bar, #send_form { background:rgba(247,253,254,.97)!important; border:1px solid #d1e2e6!important; box-shadow:0 2px 8px #3756610d!important; backdrop-filter:none!important; }
#send_form { border-radius:18px!important; }
#send_textarea { color:#354b53!important; background:transparent!important; }
#send_textarea::placeholder { color:#8ba1a9; }
@media(max-width:600px) {
 :root { --glass-avatar:84px; }
 #chat { padding:36px 9px 18px!important; }
 #chat .mes { width:100%; padding:16px 16px 40px!important; border-radius:18px!important; margin-top:38px!important; }
 #chat .mes .mesAvatarWrapper > .avatar { left:16px; height:108px!important; top:-24px; }
 #chat .mes .ch_name { min-height:78px; gap:5px; }
 #chat .mes[is_user="true"] { width:94%; }
 #chat .mes[is_user="true"] .mesAvatarWrapper > .avatar { right:16px; width:68px!important; height:80px!important; }
 #chat .mes[is_user="true"] .ch_name { margin-right:76px!important; min-height:52px; }
 #chat .mes .mesIDDisplay { left:16px; }
 #chat .mes .mes_timer { left:72px; }
 #chat .mes .tokenCounterDisplay { left:142px; }
}
